Deno.serve(async (req) => {
  const url = new URL(req.url);
  const token = url.searchParams.get('token');
  if (token !== SEED_TOKEN) {
    return new Response(JSON.stringify({ error: 'Token incorrecto' }), { status: 401, headers: { 'Content-Type': 'application/json' } });
  }
  const base44Key = Deno.env.get('BASE44_API_KEY') || '';
  if (!base44Key) return new Response(JSON.stringify({ error: 'BASE44_API_KEY no configurada' }), { status: 500, headers: { 'Content-Type': 'application/json' } });

  const BASE_URL = 'https://wtapp.base44.app';
  const hdrs = { 'api_key': base44Key, 'Content-Type': 'application/json' };

  // 1. Borrar TODO lo existente (paginado).
  let borrados = 0;
  for (let pass = 0; pass < 30; pass++) {
    const rE = await fetch(`${BASE_URL}/api/entities/ConocimientoRAG?limit=100`, { headers: hdrs });
    const arr = rE.ok ? await rE.json() : [];
    if (!arr.length) break;
    for (const it of arr) {
      try { await fetch(`${BASE_URL}/api/entities/ConocimientoRAG/${it.id}`, { method: 'DELETE', headers: hdrs }); borrados++; } catch { /* */ }
    }
  }

  // 2. Crear los nuevos.
  const resultados: any[] = [];
  for (const chunk of CHUNKS) {
    const r = await fetch(`${BASE_URL}/api/entities/ConocimientoRAG`, { method: 'POST', headers: hdrs, body: JSON.stringify(chunk) });
    if (r.ok) { const c = await r.json(); resultados.push({ titulo: chunk.titulo, id: c.id, ok: true }); }
    else { const err = await r.text(); resultados.push({ titulo: chunk.titulo, ok: false, error: err.slice(0, 200) }); console.error(`Error chunk: ${chunk.titulo}`, err.slice(0, 150)); }
  }
  const exitosos = resultados.filter((r) => r.ok).length;
  return new Response(JSON.stringify({ mensaje: `Borrados ${borrados}, creados ${exitosos}/${CHUNKS.length}`, borrados, creados: exitosos, resultados }), { status: 200, headers: { 'Content-Type': 'application/json' } });
});
